{
  "geracao_sequencia_aleatoria": {
    "julgamento": "Low",
    "justificativa": "O método descreve o uso de uma sequência de randomização gerada por computador, estratificada por centro e tipo de cirurgia, com blocos aleatórios de 2 e 4 pacientes."
  },
  "ocultacao_alocacao": {
    "julgamento": "Unclear",
    "justificativa": "O artigo especifica o uso de blocos de randomização, mas não descreve o método específico utilizado para ocultar a alocação (por exemplo, envelopes numerados ou central de randomização), impedindo a confirmação de que a ocultação foi adequada."
  },
  "cegamento_participantes_equipe": {
    "julgamento": "High",
    "justificativa": "A intervenção envolve manobras clínicas específicas (como a elevação passiva das pernas) e administração de medicamentos distintos guiados por um algoritmo, tornando o cegamento da equipe e dos pacientes impossível ou altamente improvável de ser mantido."
  },
  "cegamento_avaliadores_desfecho": {
    "julgamento": "Unclear",
    "justificativa": "O texto não relata explicitamente se os avaliadores dos desfechos clínicos (complicações, mortalidade) foram cegados ao grupo de alocação, embora o uso de uma escala de gravidade padronizada (Accordion) sugira um esforço para objetividade."
  },
  "dados_desfecho_incompletos": {
    "julgamento": "Low",
    "justificativa": "O diagrama CONSORT detalha as exclusões e perdas de acompanhamento, e a análise foi conduzida sob o princípio de intenção de tratar (intention-to-treat) incluindo a maioria dos pacientes randomizados."
  },
  "relato_seletivo": {
    "julgamento": "Low",
    "justificativa": "O registro do ensaio está documentado (NTR3380) e o artigo reporta consistentemente os desfechos primários e secundários pré-especificados, incluindo aqueles não estatisticamente significantes."
  },
  "outros_vieses": {
    "julgamento": "Unclear",
    "justificativa": "Não há evidência de vieses adicionais específicos além dos discutidos nos outros domínios, mas a falta de medição da CI no grupo controle (limitação declarada) impede uma avaliação completa do impacto isolado da intervenção."
  },
  "risco_global": {
    "julgamento": "High",
    "justificativa": "O risco de viés é classificado como alto devido à incapacidade de cegar os participantes e a equipe de cuidados à natureza da intervenção, o que pode influenciar a conduta clínica e a percepção dos desfechos."
  }
}
